frappe.ui.form.on('Product Items', {
	quantity(frm,cdt,cdn){
	    total(cdt,cdn);
	},
	product_price(frm,cdt,cdn){
	    total(cdt,cdn);
	},
	total(frm){
	    calculate_total(frm);
	},
	product_remove(frm,cdt,cdn){
	    calculate_total(frm)
	},

});

frappe.ui.form.on("Cart Items", {

    coupon_code(frm) {
        ccoupon_code(frm);
    },
    total_amount(frm) {
        ccoupon_code(frm);
    }

});

function total(cdt,cdn){
    let row = locals[cdt][cdn];
    frappe.model.set_value(cdt,cdn,"total",(row.quantity || 0)*(row.product_price ||0))

}

function calculate_total(frm){
    let total_amt = 0;
    (frm.doc.product || []).forEach(row=>{
        total_amt += row.total || 0;
    });
    frm.set_value('total_amount',total_amt);
    frm.set_value('with_discount',total_amt);
    frm.set_value('balance_amount',total_amt);
}

 function  ccoupon_code(frm){
        if(!frm.doc.coupon_code){
            frm.set_value('with_discount',frm.doc.total_amount);
            frm.set_value('balance_amount',frm.doc.total_amount);
            return;
        }
        frappe.db.get_doc("Coupon",
            frm.doc.coupon_code
        ).then(r=>{
            if(!r.active){
                frappe.msgprint("The coupon is not active!")
                frm.set_value('with_discount',frm.doc.total_amount);
                frm.set_value('balance_amount',frm.doc.total_amount);
                return;
            }

            if((frm.doc.total_amount || 0)<r.minimum_amount){
                frappe.msgprint(`Add more items upto ${r.minimum_amount}`)
            }

            let discount = (frm.doc.total_amount*r.percentage)/100;
            let discount_amount = frm.doc.total_amount - discount;

            frm.set_value("with_discount",discount_amount);
            frm.set_value("balance_amount",discount_amount);

            frappe.show_alert({
                message:`Coupon Applied with ${r.percentage}% percentage`,
                indicator:'green'
            })
        })
}

frappe.ui.form.on('Grade Sheet', {
    refresh(frm){
        frm.toggle_display("create_student",false);
    },
    roll_number(frm) {
        let roll_no = frm.doc.roll_number;

        if (!roll_no) {
            frm.set_value("student_name", "");
            frm.toggle_display("create_student", false);
            return;
        }

        frappe.db.get_value(
            "Stud",
            {
                roll_number: roll_no
            },
            [
                "name",
                "student_name"
            ]
        ).then(r => {
            if (r.message && r.message.name) {
                frm.set_value("student_name", r.message.student_name);
                frm.toggle_display("create_student", false); // also important
            } else {
                frm.set_value("student_name", "");
                frm.toggle_display("create_student", true);
            }
        });
    },

    create_student(frm) {
        let dialog = new frappe.ui.Dialog({
            title: "Create Student",

            fields: [
                {
                    fieldname: "roll_number",
                    label: "Roll Number",
                    fieldtype: "Data",
                    default: frm.doc.roll_number,
                    read_only: 1
                },
                {
                    fieldname: "student_name",
                    label: "Student Name",
                    fieldtype: "Data",
                    reqd: 1
                }
            ],

            primary_action_label: "Create",

            primary_action(values) {
                frappe.call({
                    method: "frappe.client.insert",

                    args: {
                        doc: {
                            doctype: "Stud",
                            roll_number: values.roll_number,
                            student_name: values.student_name
                        }
                    },

                    callback(r) {
                        if (r.message) {
                            frm.set_value("student_name", values.student_name);
                            frm.toggle_display("create_student", false);

                            frappe.show_alert({
                                message: `Student created with ${values.roll_number}`,
                                indicator: "blue"
                            });

                            dialog.hide();
                        }
                    }
                });
            }
        });

        dialog.show();
    }
});

